<?php $this->layout('default'); use Moves\Services\CmsContent; use Moves\Support\CmsView as V; $status = ['draft' => 'Rascunho', 'published' => 'Publicada']; $rows = CmsContent::faqs(); $edit = null; foreach ($rows as $r) { if ((string) $r['id'] === V::queryString('editar')) { $edit = $r; } } $new = V::queryString('aba') === 'nova' || $edit !== null;
$this->start('actions'); ?><a class="cms-btn" href="/conteudos">Voltar</a><?php $this->stop(); ?>
<?= V::tabs([['/conteudos/faq', 'Perguntas', count($rows), !$new], ['/conteudos/faq?aba=nova', $edit ? 'Editar pergunta' : 'Nova pergunta', null, $new]], 'Perguntas frequentes') ?>
<?php if ($new): ?><form class="cms-card" method="post" action="/acao/faq-save" data-back><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) ($edit['id'] ?? 0) ?: '' ?>"><input type="hidden" name="back" value="/conteudos/faq"><?= V::field('Pergunta', 'question', $edit['question'] ?? '', ['required' => true]) ?><?= V::field('Resposta', 'answer', $edit['answer'] ?? '', ['type' => 'textarea', 'rows' => 5, 'required' => true]) ?><div class="cms-form-grid"><?= V::field('Ordem', 'sort_order', $edit['sort_order'] ?? '0', ['type' => 'number']) ?><?= V::field('Situação', 'status', $edit['status'] ?? 'draft', ['type' => 'select', 'choices' => $status]) ?></div><div class="cms-form-end"><button class="cms-btn-primary">Salvar pergunta</button></div></form>
<?php else: ?><section class="cms-list"><?= V::listHead('Perguntas cadastradas', 'Publicadas aparecem na página inicial do site') ?><?php if ($rows === []): ?><?= V::empty('Nenhuma pergunta cadastrada.', 'Enquanto não houver pergunta publicada, o site mantém as perguntas do template.') ?><?php else: ?><div class="cms-table-wrap"><table><thead><tr><th>Pergunta</th><th>Ordem</th><th>Status</th><th class="cms-th-actions">Ações</th></tr></thead><tbody><?php foreach ($rows as $faq): ?><tr><td><strong><?= V::e($faq['question']) ?></strong></td><td><?= (int) $faq['sort_order'] ?></td><td><?= V::badge($faq['status'], $status[$faq['status']] ?? $faq['status']) ?></td><td class="cms-td-actions"><?= V::iconLink('?editar=' . (int) $faq['id'], 'Editar') ?><?= V::iconAction('faq-delete', 'Excluir', ['id' => $faq['id']], 'Excluir esta pergunta?') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php endif; ?>
